use std::{fs,io::{Write,Seek,SeekFrom},os::{fd::AsRawFd,unix::{fs::PermissionsExt,process::CommandExt}},path::PathBuf,process::{Command,Stdio,Child},sync::atomic::{AtomicUsize,Ordering},time::{Duration,Instant}};
use uasf_queue::{sys,now};
static NEXT:AtomicUsize=AtomicUsize::new(0);
struct Fixture{root:PathBuf}
impl Fixture{fn new()->Self{let root=std::env::temp_dir().join(format!("queue-process-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::SeqCst)));fs::create_dir(&root).unwrap();fs::set_permissions(&root,fs::Permissions::from_mode(0o700)).unwrap();Self{root}}}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn launch(f:&Fixture,script:&str)->Child{
 let slot=sys::lock(&f.root.join("slot-0")).unwrap();let mut job=sys::anonymous(&f.root).unwrap();let input=sys::anonymous(&f.root).unwrap();let output=sys::anonymous(&f.root).unwrap();
 let route=uasf_json::json!({"id":"test","kind":"core","binary":"/usr/bin/python3","root":f.root,"args":["-c",script]});
 job.write_all(&uasf_json::to_vec(&uasf_json::json!({"route":route,"deadline":now()+3_000_000_000u64,"bundle":f.root})).unwrap()).unwrap();job.seek(SeekFrom::Start(0)).unwrap();
 let fds=[slot.as_raw_fd(),job.as_raw_fd(),input.as_raw_fd(),output.as_raw_fd()];let mut c=Command::new(env!("CARGO_BIN_EXE_uasf-queue"));c.arg("__guardian").args(fds.iter().map(i32::to_string)).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());unsafe{c.pre_exec(move||{for fd in fds{libc::fcntl(fd,libc::F_SETFD,0);}Ok(())});}c.spawn().unwrap()
}
fn wait(child:&mut Child){let start=Instant::now();loop{if child.try_wait().unwrap().is_some(){return;}if start.elapsed()>Duration::from_secs(5){let _=child.kill();panic!("guardian did not reap");}std::thread::sleep(Duration::from_millis(5));}}
#[test]fn successful_worker_does_not_release_slot_before_delivery_ack(){let f=Fixture::new();let mut c=launch(&f,"print('{}')");let fd=c.stdout.as_ref().unwrap().as_raw_fd();sys::nonblock(fd).unwrap();let mut code=[0u8;2];sys::read_exact(fd,&mut code,now()+2_000_000_000).unwrap();assert_eq!(&code,b"0\n");assert!(sys::lock(&f.root.join("slot-0")).is_err());c.stdin.take().unwrap().write_all(b"A").unwrap();wait(&mut c);assert!(sys::lock(&f.root.join("slot-0")).is_ok());}
#[test]fn lost_supervisor_control_reaps_escaped_descendant_before_slot_reuse(){let f=Fixture::new();let marker=f.root.join("pids");let code=format!("import os,time,json\np=os.fork()\nif p==0:\n os.setsid();time.sleep(60)\nelse:\n open({:?},'w').write(json.dumps([os.getpid(),p]));time.sleep(60)",marker.to_str().unwrap());let mut c=launch(&f,&code);let until=Instant::now()+Duration::from_secs(2);while !marker.exists(){assert!(Instant::now()<until);std::thread::sleep(Duration::from_millis(5));}let v=uasf_json::from_slice(&fs::read(&marker).unwrap()).unwrap();assert!(sys::lock(&f.root.join("slot-0")).is_err());c.stdin.take();wait(&mut c);for p in v.as_array().unwrap(){assert!(sys::stat(p.as_u64().unwrap() as u32).is_none());}assert!(sys::lock(&f.root.join("slot-0")).is_ok());}
#[test]fn delivery_without_ack_has_finite_lifetime(){let f=Fixture::new();let mut c=launch(&f,"print('{}')");wait(&mut c);assert!(!c.try_wait().unwrap().unwrap().success());assert!(sys::lock(&f.root.join("slot-0")).is_ok());}
#[test]fn slow_input_deadline_is_absolute(){let mut pipe=[0;2];assert_eq!(unsafe{libc::pipe2(pipe.as_mut_ptr(),libc::O_CLOEXEC)},0);let started=now();assert!(sys::read_input(pipe[0],started+20_000_000).is_err());assert!(now()-started<500_000_000);unsafe{libc::close(pipe[0]);libc::close(pipe[1]);}}
#[test]fn slow_output_deadline_does_not_block_forever(){let mut pipe=[0;2];assert_eq!(unsafe{libc::pipe2(pipe.as_mut_ptr(),libc::O_CLOEXEC|libc::O_NONBLOCK)},0);let started=now();assert!(sys::write_deadline(pipe[1],&vec![0;1024*1024],started+20_000_000).is_err());assert!(now()-started<500_000_000);unsafe{libc::close(pipe[0]);libc::close(pipe[1]);}}
